CREATE OR REPLACE FUNCTION public.fn_get_media_asset_by_id(p_tenant_id uuid, p_id uuid)  RETURNS TABLE(id uuid, tenant_id uuid, organization_id uuid, child_id uuid, entity_type character varying, entity_id uuid, display_container character varying, display_key character varying, display_content_type character varying, display_size_bytes bigint, display_width integer, display_height integer, thumbnail_container character varying, thumbnail_key character varying, thumbnail_content_type character varying, thumbnail_size_bytes bigint, thumbnail_width integer, thumbnail_height integer, content_hash character varying, created_by uuid, created_at timestamp with time zone, updated_at timestamp with time zone)  LANGUAGE plpgsql AS $function$ BEGIN     RETURN QUERY     SELECT          m.id, m.tenant_id, m.organization_id, m.child_id, m.entity_type, m.entity_id,         m.display_container, m.display_key, m.display_content_type, m.display_size_bytes, m.display_width, m.display_height,         m.thumbnail_container, m.thumbnail_key, m.thumbnail_content_type, m.thumbnail_size_bytes, m.thumbnail_width, m.thumbnail_height,         m.content_hash, m.created_by, m.created_at, m.updated_at     FROM public.media_assets m     WHERE m.id = p_id AND m.tenant_id = p_tenant_id; END; $function$ ;
